class Lcm
  [public static]
  lcm(x: int, y: int): int
    if (x < y)
      tmp: int := x;
      x := y;
      y := tmp
    end if;
    lcm: int := x;
    while (true)
      if (lcm % y == 0)
        return lcm
      end if;
      lcm := lcm + x
    end while
  end method
end class

