class SumEvenOdd
  [public static]
  sumEvenOdd(list1: List<int>): int
    list2: List<int> := new List<>();
    for (i: int := 0; i < list1.size(); i++)
      if (list1.get(i) % 2 == 0)
        list2.add(list1.get(i))
      end if
    end for;
    for (i: int := 0; i < list2.size(); i++)
      list1.set(i, list1.get(i) + list2.get(i))
    end for;
    return list1.get(0)
  end method
end class

