class IsIsomorphic
  [public static]
  isIsomorphic(str1: string, str2: string): bool
    len1: int := str1.length();
    len2: int := str2.length();
    if (len1 != len2)
      return false
    end if;
    c1: char := str1.charAt(0);
    c2: char := str2.charAt(0);
    i1: int := 1;
    i2: int := 1;
    while (i1 < len1 && i2 < len2)
      if (c1 != c2)
        i1++;
        i2++
      else
        if (i1 >= len1)
          i1 := 0;
          return false
        else
          if (i2 >= len2)
            i2 := 0;
            return false
          else
            if (c1 == c2)
              i1++
            else
              i2++
            end if
          end if
        end if
      end if
    end while;
    return i1 == i2
  end method
end class

