class IsOdd
  [public static]
  isOdd(n: int): bool
    if (n % 2 == 0)
      return false
    end if;
    for (i: int := 2; i <= n; i := i + 2)
      if (n % i == 0)
        return false
      end if
    end for;
    return true
  end method
end class

