class SameLength
  [public static]
  sameLength(a: int, b: int): bool
    if (a < 0 || b < 0)
      return false
    end if;
    aLen: int := a + 1;
    bLen: int := b + 1;
    if (aLen < 0 || bLen < 0)
      return false
    end if;
    len: int := aLen;
    if (len < 0 || len > bLen)
      return false
    end if;
    while (aLen < bLen)
      if (a < bLen - len)
        return false
      end if;
      aLen++
    end while;
    return true
  end method
end class

