class MaxSumSubseq
  [public static]
  maxSumSubseq(a: List<int>): int
    size: int := a.size();
    sum: int := 0;
    maxSum: int := Integer.MIN_VALUE;
    prevSum: int := 0;
    currSum: int := 0;
    for (i: int := 0; i < size; i++)
      currSum := prevSum + a.get(i);
      prevSum := sum;
      sum := Math.max(sum, currSum);
      maxSum := Math.max(maxSum, sum)
    end for;
    return maxSum
  end method
end class

