  [public static]
  countUnsetBits(n: int): int
    cnt: int := 0;
    for (i: int := 1; i <= n; i++)
      temp: int := i;
      while (temp != 0)
        if ((temp & 1) == 0)
          cnt++
        end if;
        temp := temp >> 1
      end while
    end for;
    return cnt
  end method
end class

