class MaximumProduct
  [public static]
  maximumProduct(nums: List<int>): int
    n: int := nums.size();
    m: int := nums.get(0);
    max: int := 0;
    for (i: int := 0; i < n; i++)
      for (j: int := i + 1; j < n; j++)
        for (k: int := j + 1; k < n; k++)
          temp: int := nums.get(i) * nums.get(j) * nums.get(k);
          if (temp > max)
            max := temp;
            m := nums.get(i)
          end if
        end for
      end for
    end for;
    return max
  end method
end class

