class ChunkTuples
  [public static]
  chunkTuples(testTup: List<int>, n: int): List<List<int>>
    output: List<List<int>> := new List<>();
    start: int := 0;
    while (start < testTup.size())
      end: int := start + n - 1;
      if (end >= testTup.size())
        end := testTup.size() - 1
      end if;
      chunk: List<int> := new List<>();
      for (i: int := start; i <= end; i++)
        chunk.add(testTup.get(i))
      end for;
      output.add(chunk);
      start := end + 1
    end while;
    return output
  end method
end class

