class MaxProduct
  [public static]
  maxProduct(arr: List<int>): List<int>
    max: int := Integer.MIN_VALUE;
    res: List<int> := new List<>();
    for (i: int := 0; i < arr.size() - 1; i++)
      for (j: int := i + 1; j < arr.size(); j++)
        product: int := 0;
        product := arr.get(i) * arr.get(j);
        product := (product > 0) ? product : 0;
        if (product > max)
          max := product;
          res.clear();
          res.add(arr.get(i));
          res.add(arr.get(j))
        else
          if (product == max)
            res.add(arr.get(j))
          end if
        end if
      end for
    end for;
    return res
  end method
end class

