  [public static]
  subset(ar: List<int>, n: int): int
    res: int := 0;
    for (i: int := 0; i < n; i++)
      if (ar.get(i).equals(ar.get(n - 1)))
        res++
      end if
    end for;
    return res
  end method
end class

