class FloorMax
  [public static]
  floorMax(a: int, b: int, n: int): int
    diff: int := a ^ b ^ n;
    count: int := 0;
    while (diff > 0)
      diff := diff & (diff - 1);
      count++
    end while;
    return (count == 1) ? n : count
  end method
end class

