class JoinTuples
  [public static]
  joinTuples(testList: List<List<int>>): List<List<int>>
    joinedTuples: Map<int, List<int>> := new Map<>();
    foreach (List<int> tuple in testList)
      if (joinedTuples.containsKey(tuple.get(0)))
        joinedTuples.get(tuple.get(0)).add(tuple.get(1))
      else
        newTuple: List<int> := new List<>();
        newTuple.add(tuple.get(0));
        newTuple.add(tuple.get(1));
        joinedTuples.put(tuple.get(0), newTuple)
      end if
    end foreach;
    result: List<List<int>> := new List<>();
    foreach (int key in joinedTuples.keySet())
      result.add(joinedTuples.get(key))
    end foreach;
    return result
  end method
end class

