class MaximumSegments
  [public static]
  maximumSegments(n: int, a: int, b: int, c: int): int
    dp: int[] := new int[n + 10];
    Arrays.fill(dp, -1);
    dp[0] := 0;
    for (i: int := 0; i < n; i := i + 1)
      if (dp[i] != -1)
        if (i + a <= n)
          dp[i + a] := Math.max(dp[i] + 1, dp[i + a])
        end if;
        if (i + b <= n)
          dp[i + b] := Math.max(dp[i] + 1, dp[i + b])
        end if;
        if (i + c <= n)
          dp[i + c] := Math.max(dp[i] + 1, dp[i + c])
        end if
      end if
    end for;
    return dp[n]
  end method
end class

